problems.starterCode:
function hydrateUserRecords(_userIds, _fetchUser) {
  return Promise.resolve({ users: [], count: 0 });
}

module.exports = { hydrateUserRecords };

problems.solutionCode:
function validateHydrateInputs(userIds, fetchUser) {
  if (!Array.isArray(userIds)) {
    throw new TypeError('userIds must be an array');
  }
  if (typeof fetchUser !== 'function') {
    throw new TypeError('fetchUser must be a function');
  }
}

async function hydrateUserRecords(userIds, fetchUser) {
  validateHydrateInputs(userIds, fetchUser);
  if (userIds.length === 0) {
    return { users: [], count: 0 };
  }
  const users = await Promise.all(userIds.map((id) => fetchUser(id)));
  return { users, count: users.length };
}

module.exports = { hydrateUserRecords };

problems.trapMutant:
