problems.starterCode:
function probeClusterNodes(_nodes, _pingNode) {
  return Promise.resolve({ healthy: [], failed: [] });
}

module.exports = { probeClusterNodes };

problems.solutionCode:
async function probeClusterNodes(nodes, pingNode) {
  if (!Array.isArray(nodes) || typeof pingNode !== 'function') {
    throw new TypeError('nodes must be an array and pingNode must be a function');
  }
  if (nodes.length === 0) {
    return { healthy: [], failed: [] };
  }
  const settled = await Promise.allSettled(nodes.map((node) => pingNode(node)));
  const healthy = [];
  const failed = [];
  for (let i = 0; i < settled.length; i += 1) {
    const outcome = settled[i];
    const node = nodes[i];
    if (outcome.status === 'fulfilled') {
      healthy.push({ region: node.region, latencyMs: outcome.value.latencyMs });
    } else {
      const reason = outcome.reason;
      failed.push({
        region: node.region,
        error: reason instanceof Error ? reason.message : String(reason),
      });
    }
  }
  return { healthy, failed };
}

module.exports = { probeClusterNodes };

