problems.starterCode:
function authorizeCheckoutStep(_reserveInventory, _chargeCard) {
  return Promise.resolve({ ok: false, errors: [] });
}

module.exports = { authorizeCheckoutStep };

problems.solutionCode:
function formatReason(reason) {
  return reason instanceof Error ? reason.message : String(reason);
}

async function authorizeCheckoutStep(reserveInventory, chargeCard) {
  if (typeof reserveInventory !== 'function' || typeof chargeCard !== 'function') {
    throw new TypeError('reserveInventory and chargeCard must be functions');
  }
  const [invOutcome, payOutcome] = await Promise.allSettled([
    Promise.resolve().then(() => reserveInventory()),
    Promise.resolve().then(() => chargeCard()),
  ]);
  if (invOutcome.status === 'fulfilled' && payOutcome.status === 'fulfilled') {
    return {
      ok: true,
      reservation: invOutcome.value,
      payment: payOutcome.value,
    };
  }
  const errors = [];
  if (invOutcome.status === 'rejected') {
    errors.push(formatReason(invOutcome.reason));
  }
  if (payOutcome.status === 'rejected') {
    errors.push(formatReason(payOutcome.reason));
  }
  return { ok: false, errors };
}

module.exports = { authorizeCheckoutStep };

problems.trapMutant:
async function authorizeCheckoutStep(reserveInventory, chargeCard) {
  if (typeof reserveInventory !== 'function' || typeof chargeCard !== 'function') {
    throw new TypeError('reserveInventory and chargeCard must be functions');
  }
  try {
    const payPromise = chargeCard();
    const reservation = await reserveInventory();
    const payment = await payPromise;
    return { ok: true, reservation, payment };
  } catch (err) {
    return { ok: false, errors: [err instanceof Error ? err.message : String(err)] };
  }
}

module.exports = { authorizeCheckoutStep };

