problems.starterCode:
function validateDeadlineArgs(invokeRpc, deadlineMs) {
  if (typeof invokeRpc !== 'function') {
    throw new TypeError('invokeRpc must be a function');
  }
  if (!Number.isFinite(deadlineMs) || deadlineMs <= 0) {
    throw new RangeError('deadlineMs must be a positive finite number');
  }
}

function callWithDeadline(invokeRpc, deadlineMs, options = {}) {
  validateDeadlineArgs(invokeRpc, deadlineMs);
  const schedule = options.setTimeout ?? setTimeout;
  try {
    const timeoutPromise = new Promise((_, reject) => {
      schedule(() => reject(new Error('Deadline exceeded')), deadlineMs);
    });
    return Promise.race([invokeRpc().then((value) => ({ ok: true, value })), timeoutPromise]);
  } catch (err) {
    return Promise.resolve({
      ok: false,
      timedOut: err instanceof Error && err.message === 'Deadline exceeded',
      error: err instanceof Error ? err.message : String(err),
    });
  }
}

module.exports = { callWithDeadline };

problems.solutionCode:
function validateDeadlineArgs(invokeRpc, deadlineMs) {
  if (typeof invokeRpc !== 'function') {
    throw new TypeError('invokeRpc must be a function');
  }
  if (!Number.isFinite(deadlineMs) || deadlineMs <= 0) {
    throw new RangeError('deadlineMs must be a positive finite number');
  }
}

function formatDeadlineError(err, timeoutError) {
  return {
    ok: false,
    timedOut: err === timeoutError,
    error: err instanceof Error ? err.message : String(err),
  };
}

async function callWithDeadline(invokeRpc, deadlineMs, options = {}) {
  validateDeadlineArgs(invokeRpc, deadlineMs);
  const schedule = options.setTimeout ?? setTimeout;
  const cancel = options.clearTimeout ?? clearTimeout;
  let timerId;
  const timeoutError = new Error('Deadline exceeded');
  const timeoutPromise = new Promise((_, reject) => {
    timerId = schedule(() => reject(timeoutError), deadlineMs);
  });
  try {
    const value = await Promise.race([Promise.resolve().then(() => invokeRpc()), timeoutPromise]);
    return { ok: true, value };
  } catch (err) {
    return formatDeadlineError(err, timeoutError);
  } finally {
    cancel(timerId);
  }
}

module.exports = { callWithDeadline };

